initDecor();
function doAction(a){if(!gameOn||paused)return;const now=performance.now()/1000;if(a==='attack'&&player.attackCd<=0){player.combo=player.combo%3+1;player.anim='attack';player.actionT=.38;player.attackCd=.25;player.face='angry';hitStop=.07;shake=3;let hit=false;for(const e of enemies){if(!e.alive||dist(player,e)>72)continue;if((e.x-player.x)*player.dir < -20)continue;e.hp-=14+player.sword*5;e.hit=.22;e.vx=player.dir*220;e.vy=-70;hit=true;particlesBurst(e.x,e.y-18,'#ffe68b',10);if(e.hp<=0)killEnemy(e);}if(hit)say(['Slash!','Cross cut!','Finisher!'][player.combo-1]);}
if(a==='jump'&&player.air<=0){player.air=1;player.anim='jump';player.vy=-220;player.actionT=.4;particlesBurst(player.x,player.y,'#d7e5b4',5)}
if(a==='roll'&&player.rollCd<=0){player.anim='roll';player.actionT=.48;player.invul=.52;player.rollCd=.8;player.vx=player.dir*330;particlesBurst(player.x,player.y,'#c9d4c0',6)}
if(a==='block'){player.anim='block';player.actionT=.35;player.face='angry'}
if(a==='skill1'||a==='skill2'||a==='ult'){if(!player.fruit){say('Find and eat a Devil Fruit first!');return}const ult=a==='ult',cost=ult?70:25;if(player.en<cost){say('Not enough energy!');return}player.en-=cost;castPower(a,ult)} }
function castPower(a,ult){const f=fruitData[player.fruit-1];player.anim='power';player.actionT=ult?1.8:.65;player.face='angry';const power=ult?38:22,range=ult?210:145;effects.push({x:player.x,y:player.y,type:'burst',color:f.color,t:ult?1.6:.6,max:ult?1.6:.6,r:range,fruit:player.fruit});let n=0;for(const e of enemies){if(e.alive&&dist(player,e)<range){e.hp-=power;e.hit=.3;e.vx=(e.x-player.x)/(dist(player,e)||1)*(ult?270:190);e.vy=(e.y-player.y)/(dist(player,e)||1)*100;particlesBurst(e.x,e.y-18,f.glow,ult?16:8);if(player.fruit===2)e.frozen=ult?2.5:1.2;if(e.hp<=0)killEnemy(e);n++;if(player.fruit===3&&a!=='ult'&&n<3)continue;}}if(player.fruit===0){}if(player.fruit===1||player.fruit===4)effects.push({x:player.x+player.dir*75,y:player.y+20,type:'pool',color:f.color,t:4,max:4,r:70});if(player.fruit===2)frozen.push({x:player.x,y:player.y,r:90,t:4});if(player.fruit===3){for(let i=0;i<Math.min(n,4);i++)effects.push({x:player.x+rand(-140,140),y:player.y+rand(-100,100),type:'zap',color:f.color,t:.4,max:.4,r:8});}if(player.fruit===5){player.vx=player.dir*(ult?390:260)}say(ult?'ULTIMATE!  '+f.name+' unleashed!':f.name+' skill!');shake=ult?7:4;}
function killEnemy(e){e.alive=false;player.gold+=e.boss?150:12+Math.floor(wave*1.5);player.xp+=e.boss?150:25;particlesBurst(e.x,e.y-16,'#ffd978',14);if(Math.random()<.16||e.boss)dropFruit(e.x,e.y,Math.floor(Math.random()*fruitData.length));if(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=12;player.hp=player.maxHp;player.maxEn+=5;player.en=player.maxEn;say('LEVEL UP! Now level '+player.level+' · stats improved');}if(enemies.every(x=>!x.alive)){wave++;setTimeout(()=>{if(gameOn)spawnWave()},800)}}
function particlesBurst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=rand(30,170);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-35,t:rand(.22,.7),life:rand(.22,.7),color,size:rand(2,5)})}}
function nearestFruit(){let f=null,d=52;for(const x of fruits)if(x.alive&&dist(player,x)<d){f=x;d=dist(player,x)}return f;}
function showFruit(f){openFruit=f;const data=fruitData[f.type];$('fruitTitle').textContent=data.name;$('fruitDesc').textContent=data.desc;$('fruitScreen').classList.remove('hidden');paused=true;mode='fruit';}
function fruitChoice(choice){if(!openFruit)return;if(choice==='eat'){player.fruit=openFruit.type+1;$('fruitLabel').textContent=fruitData[openFruit.type].name.toUpperCase();say('You ate the '+fruitData[openFruit.type].name+'!');}else if(choice==='store'){inventory.push(openFruit.type);say(fruitData[openFruit.type].name+' stored in your bag.')}openFruit.alive=false;openFruit=null;$('fruitScreen').classList.add('hidden');paused=false;mode='play';}
$('eatFruit').onclick=()=>fruitChoice('eat');$('storeFruit').onclick=()=>fruitChoice('store');$('leaveFruit').onclick=()=>{openFruit=null;$('fruitScreen').classList.add('hidden');paused=false;mode='play'};
function openPanel(page){if(!gameOn)return;paused=true;mode=page;$('panelScreen').classList.remove('hidden');renderPanel(page)}
function closePanel(){ $('panelScreen').classList.add('hidden');paused=false;mode='play'}
function renderPanel(page){const box=$('panelContent');let content='';if(page==='character'){content=`<div class="tag">PIRATE PROFILE</div><h2>Character</h2><canvas id="preview" width="180" height="190" style="width:180px;height:190px;background:#416e68;border:2px solid #d5c997;image-rendering:pixelated"></canvas><div class="stats"><div class="stat">LEVEL <b>${player.level}</b></div><div class="stat">GOLD <b>${player.gold} ฿</b></div><div class="stat">MELEE <b>${player.melee}</b></div><div class="stat">SWORD <b>${player.sword}</b></div><div class="stat">DEFENSE <b>${player.defense}</b></div><div class="stat">FRUIT <b>${player.fruit?fruitData[player.fruit-1].name:'None'}</b></div></div><p>Customize your look</p><div class="row"><label>Hair <input type="color" value="${player.custom.hair}" onchange="setColor('hair',this.value)"></label><label>Vest <input type="color" value="${player.custom.vest}" onchange="setColor('vest',this.value)"></label><label>Bandana <input type="color" value="${player.custom.band}" onchange="setColor('band',this.value)"></label></div><div class="row"><button onclick="saveGame()">SAVE</button><button onclick="closePanel()">BACK</button></div>`;}else if(page==='inventory'){content=`<div class="tag">YOUR BELONGINGS</div><h2>Inventory</h2><p>Devil Fruits: ${inventory.length?inventory.map(i=>fruitData[i].name).join(' · '):'Your bag is empty.'}</p><div class="row">${inventory.map((i,n)=>`<button onclick="equipStored(${n})">EQUIP ${fruitData[i].name.split(' ')[0]}</button>`).join('')}</div><p>Gold: ${player.gold} ฿</p><button onclick="closePanel()">BACK</button>`;}else if(page==='map'){content=`<div class="tag">LOG POSE</div><h2>Tidebound Island</h2><canvas id="mapCanvas" width="300" height="190" style="width:min(300px,70vw);height:auto;background:#71a978;border:2px solid #d5c997"></canvas><p>Village · Forest · Sunlit Beach · Old Docks</p><button onclick="closePanel()">BACK</button>`;}else if(page==='settings'){content=`<div class="tag">OPTIONS</div><h2>Settings</h2><p>Day & night cycle <button onclick="timeOfDay=(timeOfDay+.25)%1">CHANGE TIME</button></p><p>Touch controls are ${innerWidth<innerHeight?'on':'available'} · Keyboard controls always active</p><button onclick="saveGame()">SAVE ADVENTURE</button><div class="row"><button onclick="closePanel()">BACK</button></div>`;}else{content=`<div class="tag">ADVENTURE PAUSED</div><h2>Take a breather</h2><div class="row"><button onclick="closePanel()">RESUME</button><button onclick="saveGame()">SAVE</button><button onclick="openPanel('character')">CHARACTER</button><button onclick="openPanel('settings')">SETTINGS</button><button onclick="goTitle()">TITLE</button></div>`;}box.innerHTML=content;if(page==='character')drawPreview();if(page==='map')drawMap();}
function equipStored(n){let type=inventory.splice(n,1)[0];player.fruit=type+1;$('fruitLabel').textContent=fruitData[type].name.toUpperCase();say(fruitData[type].name+' equipped!');renderPanel('inventory')}
function setColor(key,value){player.custom[key]=value;drawPreview()}
window.setColor=setColor;window.closePanel=closePanel;window.saveGame=saveGame;window.equipStored=equipStored;window.openPanel=openPanel;window.goTitle=()=>{saveGame();gameOn=false;paused=true;$('panelScreen').classList.add('hidden');$('start').classList.remove('hidden')};

