for(let i=0;i<60;i++){let x=(i*173+elapsed*18)%W,y=(i*97+Math.sin(elapsed+i)*8)%H;rect(x,y,rand(3,8),1,'#9bddd0')}
// paths winding through village
ctx.strokeStyle='#c9a76b';ctx.lineWidth=28;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(ox+270,oy+1200);ctx.bezierCurveTo(ox+700,oy+1110,ox+850,oy+870,ox+1200,oy+930);ctx.bezierCurveTo(ox+1470,oy+950,ox+1580,oy+550,ox+1940,oy+460);ctx.stroke();ctx.strokeStyle='#e1c582';ctx.lineWidth=1;ctx.stroke();
// screen-space beach/dock details
