function shade(hex,n){let q=parseInt(hex.slice(1),16),r=clamp((q>>16)+n,0,255),g=clamp(((q>>8)&255)+n,0,255),b=clamp((q&255)+n,0,255);return '#'+((1<<24)|(r<<16)|(g<<8)|b).toString(16).slice(1)}
function buildIsland(){
 decor=[];houses=[];garden=[];paths=[];water=[];boats=[];trees=[];
 // A curving inlet and a stone bridge create a strong, readable island layout.
 water.push({x:0,y:0,w:world.w,h:world.h});
 paths.push([[260,960],[420,890],[610,865],[810,900],[1010,920],[1190,850],[1370,760],[1580,720],[1790,760],[2050,830]],
 [[970,915],[990,700],[1080,520],[1200,360]],[[1190,850],[1280,1040],[1450,1160],[1680,1210],[1940,1170]],[[560,900],[500,1090],[400,1240]]);
 // Harbor piers, planked and irregularly spaced.
 for(let i=0;i<5;i++)boats.push({x:300+i*120,y:530+Math.sin(i*1.7)*50,a:rand(-.08,.08),c:['#a95f44','#416d7c','#c78e4f'][i%3]});
 // Houses deliberately offset around the village green.
 [[670,610,140,110,0],[900,520,132,105,1],[1240,560,150,112,2],[1450,650,138,106,0],[720,1110,150,112,2],[1030,1190,144,106,1],[1510,960,142,112,0],[1790,920,150,108,2],[380,780,130,100,1]].forEach(([x,y,w,h,t])=>houses.push({x,y,w,h,t,door:rand(.35,.65)}));
 for(let i=0;i<38;i++){let x=rand(80,world.w-70),y=rand(130,world.h-120);if(inTown(x,y))continue;trees.push({x,y,s:rand(.75,1.3),tone:Math.floor(rand(0,4)),phase:rand(0,6)});}
 for(let i=0;i<70;i++){let x=rand(270,2020),y=rand(330,1450);if(inTown(x,y)&&Math.random()>.35)garden.push({x,y,kind:Math.floor(rand(0,4)),phase:rand(0,7)});}
}
function inTown(x,y){return x>560&&x<1920&&y>430&&y<1330}
function makeEnemy(type='Bandit',boss=false){let s=styles.find(q=>q.n===type)||styles[0],a=rand(0,Math.PI*2),r=rand(220,380);return{x:clamp(player.x+Math.cos(a)*r,120,world.w-120),y:clamp(player.y+Math.sin(a)*r,120,world.h-120),vx:0,vy:0,hp:boss?300+wave*35:50+wave*8,maxHp:boss?300+wave*35:50+wave*8,style:s,boss,anim:'idle',t:rand(0,2),attack:0,wind:0,cd:rand(.4,1.8),flash:0,dead:0,stun:0,mode:'approach',seed:rand(0,100),frozen:0,burn:0,hitCd:0,retreat:0}}
function beginWave(){let n=Math.min(3+wave,9);enemies=[];for(let i=0;i<n;i++){let type=wave%3===0?pick(['Marine','Pirate','Bandit']):wave%2?pick(['Bandit','Pirate']):pick(['Marine','Bandit']);enemies.push(makeEnemy(type,false))}if(wave%5===0)enemies.push(makeEnemy('Captain',true));$('objective').textContent=`WAVE ${wave} · ${enemies.length} RIVALS`;say(wave%5===0?'A rival captain has arrived!':`Wave ${wave} — rival crew incoming`)}
function resetGame(){player.x=1200;player.y=980;player.hp=player.maxHp=120;player.en=player.maxEn=100;player.level=1;player.xp=0;player.gold=0;player.fruit=-1;player.action='';player.anim='idle';player.combo=0;wave=1;fruitDropDone=false;inventory=[];particles=[];projectiles=[];effects=[];marks=[];buildIsland();beginWave();paused=false;gameOn=true;mode='play';$('start').classList.add('hidden');$('overlay').classList.add('hidden');updateHud();saveGame()}
function saveGame(){try{localStorage.setItem('tidebound-save',JSON.stringify({x:player.x,y:player.y,hp:player.hp,en:player.en,level:player.level,xp:player.xp,gold:player.gold,fruit:player.fruit,inventory,wave,fruitDropDone}))}catch(e){}}
function loadGame(){try{let s=JSON.parse(localStorage.getItem('tidebound-save'));if(!s)return false;Object.assign(player,{x:s.x||1200,y:s.y||980,hp:s.hp||120,en:s.en||100,level:s.level||1,xp:s.xp||0,gold:s.gold||0,fruit:Number.isInteger(s.fruit)?s.fruit:-1});inventory=s.inventory||[];wave=s.wave||1;fruitDropDone=!!s.fruitDropDone;buildIsland();beginWave();paused=false;gameOn=true;mode='play';$('start').classList.add('hidden');updateHud();return true}catch(e){return false}}
function spawnParticle(x,y,color,life=.5,size=3,vx=rand(-60,60),vy=rand(-90,25),kind='spark'){if(particles.length>500)return;let p=particlePool.pop()||{};Object.assign(p,{x,y,color,life,max:life,size,vx,vy,kind,rot:rand(0,6),spin:rand(-4,4)});particles.push(p)}
function burst(x,y,color,n=18,kind='spark'){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(30,190);spawnParticle(x,y,color,rand(.25,.85),rand(2,5),Math.cos(a)*v,Math.sin(a)*v,kind)}}
function setAction(name){if(!gameOn||paused)return;if(name==='block'){player.action='block';return}if(name==='attack'){if(player.attackCd>0||player.stun>0)return;player.combo=(player.combo%3)+1;player.action='slash';player.actionT=0;player.attackCd=.34;player.anim='attack';return}if(name==='jump'){if(player.air<=0){player.jumpV=205;player.air=.55;player.anim='jump';spawnParticle(player.x,player.y,'#d7c99a',5,'dust')}return}if(name==='roll'){if(player.rollCd>0||player.stun>0)return;player.action='roll';player.actionT=.38;player.rollCd=.85;player.invul=.38;player.anim='roll';return}if(name==='skill1'||name==='skill2'||name==='ult'){castPower(name)}}
function nearestEnemy(range=120){let best=null,bd=range;for(let e of enemies){if(e.dead)continue;let d=dist(player,e);if(d<bd){bd=d;best=e}}return best}
function damageEnemy(e,n,kind='steel'){if(!e||e.dead||e.hitCd>0)return;e.hp-=n;e.flash=.07;e.hitCd=.12;e.stun=.16;e.vx+=(e.x-player.x)*.8;e.vy+=(e.y-player.y)*.8;hitStop=Math.max(hitStop,.07);shake=Math.max(shake,3);burst(e.x,e.y-16,kind==='ice'?'#d8ffff':kind==='fire'?'#ffb052':'#f8e6ab',8);if(e.hp<=0){e.dead=.01;e.anim='death';player.xp+=e.boss?150:35;player.gold+=e.boss?80:rand(8,19)|0;if(e.boss)say('Captain defeated! The island is safe—for now.');if(!fruitDropDone){fruitDropDone=true;objects.push({type:'fruit',x:e.x+rand(-20,20),y:e.y,kind:Math.floor(Math.random()*fruitKinds.length),bob:0});say('A strange fruit has appeared! Find it and interact.')}if(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=12;player.hp=player.maxHp;player.maxEn+=5;player.en=player.maxEn;say(`Level up! You are now level ${player.level}.`)}saveGame()}}
function swordHit(){let reach=57+player.sword*4,arc=player.combo===2?1.05:1.28;for(let e of enemies){if(e.dead)continue;let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),forward=player.dir;let front=dx*forward;if(d<reach&&front>-20&&Math.abs(dy)<42){damageEnemy(e,20+player.level*3+player.sword*4);}}
 let fx=player.x+player.dir*28,fy=player.y-15;effects.push({type:'slash',x:fx,y:fy,t:0,life:.27,dir:player.dir,combo:player.combo});for(let i=0;i<8;i++)spawnParticle(fx+player.dir*rand(-8,25),fy+rand(-20,15),'#fff0ab',.22,2,player.dir*rand(20,80),rand(-50,30),'spark')}
function castPower(kind){if(player.fruit<0){say('Find and eat a Devil Fruit first.');return}if(player.powerCd>0||player.en<(kind==='ult'?50:18))return;let cost=kind==='ult'?50:18;player.en-=cost;player.powerCd=kind==='ult'?4:kind==='skill2'?1.5:1.1;let fruit=fruitKinds[player.fruit],type=fruit.fx;player.action=kind;player.actionT=kind==='ult'?5.4:.5;player.anim='power';if(kind==='ult'){cinema=5.4;$('barTop').style.height='8vh';$('barBottom').style.height='8vh';say(`${fruit.name} — ULTIMATE!`)}let targets=enemies.filter(e=>!e.dead&&dist(e,player)<(kind==='ult'?300:kind==='skill2'?200:165));let center={x:player.x+player.dir*(kind==='skill1'?105:65),y:player.y-12};effects.push({type,fruit:type,x:center.x,y:center.y,t:0,life:kind==='ult'?5.4:1.05,kind:kind==='ult'?'ult':kind});
 if(type==='fire'||type==='dragon'){if(kind==='skill1'){projectiles.push({x:player.x+player.dir*25,y:player.y-25,vx:player.dir*310,vy:0,life:1.1,kind:'fire',damage:42+player.level*3,r:22})}else if(kind==='skill2'){effects.push({type:'wave',x:player.x,y:player.y,t:0,life:.8,dir:player.dir,fruit:type});for(let e of targets)if((e.x-player.x)*player.dir>-40)damageEnemy(e,48,'fire')}else{for(let e of enemies)if(!e.dead&&dist(e,player)<300)damageEnemy(e,105,'fire');burst(player.x,player.y-35,'#ffb14d',60,'fire')}}
 else if(type==='ice'){for(let e of targets){damageEnemy(e,kind==='ult'?90:40,'ice');e.frozen=kind==='ult'?2.8:1.5}burst(center.x,center.y,'#b9f8ff',kind==='ult'?65:32,'ice')}
 else if(type==='light'){let chain=targets.slice(0,kind==='ult'?9:4);for(let e of chain){damageEnemy(e,kind==='ult'?75:34);effects.push({type:'bolt',x:player.x,y:player.y-20,x2:e.x,y2:e.y-14,t:0,life:.3})}}
 else if(type==='magma'){for(let e of targets){damageEnemy(e,kind==='ult'?92:40,'fire');e.burn=2.2}marks.push({x:center.x,y:center.y,t:0,life:4,kind:'lava'});burst(center.x,center.y,'#ff6935',40,'fire')}
 else if(type==='rubber'||type==='dough'||type==='magnet'||type==='shadow'||type==='tide'||type==='blossom'){for(let e of targets){damageEnemy(e,kind==='ult'?95:38,type==='ice'?'ice':'steel');if(type==='magnet'||type==='tide'){e.vx+=(player.x-e.x)*1.5;e.vy+=(player.y-e.y)*1.5}}burst(center.x,center.y,fruitKinds[player.fruit].color,kind==='ult'?70:32,type==='blossom'?'petal':'spark')}
}

