 if(toastT>0&&(toastT-=dt)<=0)$('toast').classList.add('hidden');if(hitStop>0){hitStop-=dt;return}if(cinema>0){cinema=Math.max(0,cinema-dt);if(cinema===0){$('barTop').style.height='0';$('barBottom').style.height='0'}}
 let ix=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0)+moveTouch.x,iy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0)+moveTouch.y;let mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag}
