 if(player.action==='slash'){player.actionT+=dt;if(player.actionT>.075&&player.actionT<.14)swordHit();if(player.actionT>.29)player.action=''}
 if(player.action==='block'&&!keys.i)player.action='';player.anim=player.action==='roll'?'roll':player.action==='block'?'block':player.action==='slash'?'attack':player.air>0?'jump':mag>.12?(running?'run':'walk'):'idle';
 for(let e of enemies){e.t+=dt;e.hitCd=Math.max(0,e.hitCd-dt);e.flash=Math.max(0,e.flash-dt);e.stun=Math.max(0,e.stun-dt);e.frozen=Math.max(0,e.frozen-dt);e.burn=Math.max(0,e.burn-dt);e.cd-=dt;if(e.dead){e.dead+=dt;continue}if(e.burn>0&&Math.random()<dt*2)spawnParticle(e.x+rand(-9,9),e.y-20,'#ff7b37',.35,3,rand(-12,12),-30,'fire');if(e.burn>0&&Math.random()<dt*1.6){e.hp-=3;if(e.hp<=0){e.hp=1;damageEnemy(e,2,'fire')}}
