function openPanel(which='character'){
 if(which==='dead'){$('panel').innerHTML=`<div class="eyebrow">THE TIDE TURNS</div><h2 class="title">YOU FELL</h2><p>Your crew pulls you back to the harbor. The rival wave is still waiting.</p><div class="row"><button data-act="retry">TRY AGAIN</button><button data-act="save">SAVE</button></div>`;}
