button{font:inherit;color:#fff;background:#294956;border:2px solid #edcf7b;padding:10px 13px;box-shadow:0 3px #08161c;cursor:pointer;touch-action:manipulation}
button:active{transform:translateY(2px);box-shadow:0 1px #08161c}
.panel button{min-width:118px}
.small{font-size:11px;color:#b8c9c4}
