async page => {
  const original = await page.evaluate(() => localStorage.getItem('tidebound-save'));
  let injected = false;
  await page.route('http://localhost:3002/**', async route => {
    if (route.request().resourceType() !== 'document') return route.continue();
    const response = await route.fetch();
    let html = await response.text();
    const marker = ' buildIsland();updateHud();if(!localStorage.getItem(\'tidebound-save\'))';
    const exposure = ' window.__tideTest={player,enemies,objects,fruitKinds,damageEnemy,interact,update,saveGame,loadGame,resetGame,get wave(){return wave}}; buildIsland();updateHud();if(!localStorage.getItem(\'tidebound-save\'))';
    if (!html.includes(marker)) throw new Error('injection marker missing');
    html = html.replace(marker, exposure);
    injected = html.includes('window.__tideTest={');
    await route.fulfill({ response, body: html });
  });
  await page.evaluate(() => localStorage.removeItem('tidebound-save'));
  await page.reload();
  await page.waitForFunction(() => window.__tideTest);
  await page.evaluate(() => window.__tideTest.resetGame());
  const combat = await page.evaluate(() => {
    const t = window.__tideTest;
    for (const e of [...t.enemies]) { e.hitCd = 0; t.damageEnemy(e, 10000); }
    for (let i=0; i<10; i++) t.update(.04);
    return { wave:t.wave, enemies:t.enemies.length, drops:t.objects.filter(o=>o.type==='fruit').length, saved:JSON.parse(localStorage.getItem('tidebound-save')) };
  });
  if (combat.wave < 2 || !combat.drops) throw new Error('Combat progression/fruit drop failed: '+JSON.stringify(combat));
  await page.evaluate(() => { const t=window.__tideTest, o=t.objects.find(o=>o.type==='fruit'); t.player.x=o.x; t.player.y=o.y; t.interact(); });
  await page.locator('#eat').click();
  const eaten = await page.evaluate(() => ({fruit:window.__tideTest.player.fruit, modal:!document.querySelector('#fruitModal').classList.contains('hidden'), save:JSON.parse(localStorage.getItem('tidebound-save'))}));
  if (eaten.fruit < 0 || eaten.modal || eaten.save.fruit !== eaten.fruit) throw new Error('Fruit eat/save failed: '+JSON.stringify(eaten));
  await page.evaluate(() => { const t=window.__tideTest; t.objects.push({type:'fruit',x:t.player.x,y:t.player.y,kind:(t.player.fruit+1)%t.fruitKinds.length,bob:0}); t.interact(); });
  await page.locator('#store').click();
  const stored = await page.evaluate(() => ({fruit:window.__tideTest.player.fruit, bag:JSON.parse(localStorage.getItem('tidebound-save')).inventory, drops:window.__tideTest.objects.filter(o=>o.type==='fruit').length, modal:!document.querySelector('#fruitModal').classList.contains('hidden')}));
  if (stored.bag.length !== 1 || stored.modal || stored.drops) throw new Error('Fruit store/save failed: '+JSON.stringify(stored));
  await page.evaluate(() => window.__tideTest.saveGame());
  await page.reload();
  await page.waitForFunction(() => window.__tideTest);
  const loadedOK = await page.evaluate(() => window.__tideTest.loadGame());
  const loaded = await page.evaluate(() => ({fruit:window.__tideTest.player.fruit, inventory:JSON.parse(localStorage.getItem('tidebound-save')).inventory, wave:window.__tideTest.wave, level:document.querySelector('#level').textContent}));
  if (!loadedOK || loaded.fruit !== eaten.fruit || loaded.inventory.length !== 1 || loaded.wave !== combat.wave) throw new Error('Save/load failed: '+JSON.stringify({loadedOK,loaded}));
  await page.unrouteAll();
  await page.evaluate(value => { if (value === null) localStorage.removeItem('tidebound-save'); else localStorage.setItem('tidebound-save', value); }, original);
  await page.reload();
  return {injected,combat,eat:eaten,store:stored,load:loaded};
}

